body.script:
(function () {
  var elid = document.getElementById("donnees");
  if (!elid) return;
  var D;
  try { D = JSON.parse(elid.textContent); }
  catch (e) { return; }
  if (!D || !D.zones) return;
  var svg = document.getElementById("carte");
  if (!svg) return;
  var NS = "http://www.w3.org/2000/svg";
  var el = function (n, a) { var e = document.createElementNS(NS, n);
    for (var k in (a || {})) e.setAttribute(k, a[k]); return e; };

  /* ---------- les icônes, une forme par type ---------- */
  var COULEURS = {
    conteneur:"#3b82f6", volume:"#22c55e", base:"#f59e0b", serveur:"#f59e0b",
    site:"#64748b", "page-tour":"#c084fc", agent:"#e2e8f0", patron:"#fbbf24",
    outil:"#f87171", internet:"#94a3b8"
  };
  var LIBELLES = {
    conteneur:"conteneur", volume:"volume", base:"base", serveur:"serveur",
    site:"site", "page-tour":"page de la tour", agent:"agent", patron:"Patrick",
    outil:"outil", internet:"internet"
  };

  function icone(type, taille) {
    var c = COULEURS[type] || "#64748b";
    var g = document.createElementNS(NS, "g");
    var t = taille || 34;
    function p(d) { var x = el("path", {d:d, fill:"none", stroke:c,
      "stroke-width":2, "stroke-linecap":"round", "stroke-linejoin":"round"});
      g.appendChild(x); return x; }
    function f(d) { var x = el("path", {d:d, fill:c}); g.appendChild(x); return x; }
    switch (type) {
      case "internet": /* un globe */
        f("M"+(t/2)+" 3 A "+(t/2-3)+" "+(t/2-3)+" 0 1 0 "+(t/2)+" "+(t-3)+" A "+(t/2-3)+" "+(t/2-3)+" 0 1 0 "+(t/2)+" 3");
        p("M3 "+(t/2)+" H"+(t-3)+" M"+(t/2)+" 3 C"+(t/2-8)+" "+(t/2-4)+" "+(t/2-8)+" "+(t/2+4)+" "+(t/2)+" "+(t-3)+" M"+(t/2)+" 3 C"+(t/2+8)+" "+(t/2-4)+" "+(t/2+8)+" "+(t/2+4)+" "+(t/2)+" "+(t-3));
        break;
      case "serveur": /* une tour serveur */
        f("M8 4 H"+(t-8)+" V"+(t-4)+" H8 Z");
        if (t >= 20) {
          for (var i=0;i<3;i++) { el("rect",{x:12,y:8+i*8,width:t-24,height:3,rx:1,fill:"#0d1526"},g); }
          el("circle",{cx:t-14,cy:8, r:1.6,fill:"#22c55e"},g);
          el("circle",{cx:t-14,cy:16,r:1.6,fill:"#22c55e"},g);
          el("circle",{cx:t-14,cy:24,r:1.6,fill:"#f87171"},g);
        }
        break;
      case "base": /* un cylindre */
        el("ellipse",{cx:t/2,cy:7,rx:t/2-5,ry:4,fill:c},g);
        el("rect",{x:5,y:7,width:t-10,height:t-14,fill:c},g);
        el("ellipse",{cx:t/2,cy:t-7,rx:t/2-5,ry:4,fill:"#0d1526"},g);
        break;
      case "volume": /* un disque */
        el("ellipse",{cx:t/2,cy:t/2,rx:t/2-3,ry:t/2-4,fill:"none",stroke:c,"stroke-width":2},g);
        el("circle",{cx:t/2,cy:t/2,r:5,fill:c},g);
        p("M7 10 L13 6 M"+(t-7)+" 10 L"+(t-13)+" 6");
        break;
      case "conteneur": /* une boîte */
        f("M8 6 H"+(t-8)+" L"+(t-4)+" "+(t/2)+" L"+(t-8)+" "+(t-6)+" H8 Z");
        f("M8 6 V"+(t-6)+" L"+(t-8)+" "+(t-6)+" V"+(t/2)+" L8 6 Z");
        p("M8 6 L"+(t-8)+" "+(t/2)+" M"+(t-8)+" "+(t/2)+" V"+(t-6));
        break;
      case "site": case "page-tour": /* un écran */
        if (t >= 20) {
          el("rect",{x:5,y:8,width:t-10,height:t-16,rx:2,fill:c},g);
          el("rect",{x:8,y:11,width:t-16,height:t-22,fill:"#0d1526"},g);
          el("rect",{x:t/2-4,y:t-7,width:8,height:3,fill:c},g);
          el("rect",{x:t/2-8,y:t-4,width:16,height:2,fill:c},g);
        }
        break;
      case "agent": /* une silhouette */
        el("circle",{cx:t/2,cy:t/2-7,r:6,fill:"none",stroke:c,"stroke-width":2},g);
        p("M"+(t/2-9)+" "+(t-5)+" a9 9 0 0 1 18 0");
        break;
      case "patron": /* une étoile */
        var pts="",cx=t/2,cy=t/2;
        for (var k=0;k<10;k++){var r=(k%2?6:12),a=Math.PI/2+k*Math.PI/5;
          pts+=(k?"L":"M")+(cx+r*Math.cos(a)).toFixed(1)+" "+(cy-r*Math.sin(a)).toFixed(1);}
        f(pts+" Z");
        break;
      case "outil": /* une clé */
        p("M"+(t/2)+" "+(t-6)+" A 8 8 0 1 1 "+(t/2)+" 10 M"+(t/2)+" 14 V6 M"+(t/2)+" 10 V6");
        break;
      default:
        el("rect",{x:6,y:6,width:t-12,height:t-12,rx:3,fill:"none",stroke:c,"stroke-width":2},g);
    }
    return g;
  }

  /* ---------- barre de zones ---------- */
  var bar = document.getElementById("zonebar");
  D.zones.forEach(function (z, i) {
    var b = document.createElement("button");
    b.className = "zbtn" + (i === 0 ? " actif" : "");
    b.innerHTML = z.nom + '' + z.noeuds.length + '';
    b.addEventListener("click", function () { dessiner(i); });
    bar.appendChild(b);
  });

  /* ---------- barre de groupes (sous-onglets par registre) --------- */
  var grpbar = document.getElementById("grpbar");
  var groupeActif = null;
  function groupeDe(nd) {
    // page de la tour : le registre est au debut du detail (« Piloter · /tour/... »)
    if (nd.type === "page-tour") {
      var d = (nd.detail || "").split("·")[0].trim();
      // les pages des circuits ont leur propre onglet, quelle que soit la zone du menu
      if (/circuit|flux des|pacman/.test((nd.nom || "") + " " + (nd.detail || ""))) return "Circuits";
      return d ? d : "Pages";
    }
    if (nd.type === "site") return "Sites";
    if (nd.type === "outil") return familleOutil(nd.nom);
    return "Infrastructure";
  }
  function familleOutil(nom) {
    if (/^test-|^test_|test-agents|test-chloe|test-demo|test-espaces|test-garde|test-grand|test-memoire|test-pannes|test-specs|test-vault/.test(nom)) return "Tests";
    if (/^garde|garde-fou|gardefous/.test(nom)) return "Garde-fous";
    if (/deploy|^maj-|^migrer|^promouvoir|^module\./.test(nom)) return "Déploiement";
    if (/backup|^archiver|sauvegarde|offsite/.test(nom)) return "Sauvegarde";
    if (/atelier|^tache|^mission|^instances|^file-attente|^ordre/.test(nom)) return "Atelier & missions";
    if (/veille|sentinelle|heartbeat|surveiller|relever|alerte/.test(nom)) return "Veille & alertes";
    if (/^verif|^check|^test|^controle|^audit|^pentest/.test(nom)) return "Contrôles & sécurité";
    if (/^push|^commit|^pull|^git/.test(nom)) return "Git & push";
    if (/^braignak|^clark|^chloe|^raphael|^equipage|^agents|^membre/.test(nom)) return "Agents";
    if (/^mail|^smtp|^stripe|^paiement|^coffre|^vault|^secret|^cle/.test(nom)) return "Mails, paiement & secrets";
    if (/^carte|^carto|^carte-json|^carte-zones/.test(nom)) return "Cartes";
    if (/^demo/.test(nom)) return "Démo";
    if (/^noter|^fin-de-travail|^recap|^resume|^fiche|^journal|^session/.test(nom)) return "Comptes rendus";
    return "Autres outils";
  }
  function groupesDe(zone) {
    var m = {};
    zone.noeuds.forEach(function (nd) {
      var g = groupeDe(nd); m[g] = (m[g] || 0) + 1;
    });
    var cles = Object.keys(m).sort(function (a, b) {
      return m[b] - m[a];
    });
    return cles;
  }
  function construireGroupes(zone) {
    while (grpbar.firstChild) grpbar.removeChild(grpbar.firstChild);
    var cles = groupesDe(zone);
    if (cles.length <= 1) { grpbar.style.display = "none"; groupeActif = null; return; }
    grpbar.style.display = "flex";
    // bouton « tout »
    var t = document.createElement("button");
    t.className = "gbtn actif"; t.textContent = "Tout";
    t.addEventListener("click", function () {
      groupeActif = null;
      var bs = grpbar.querySelectorAll(".gbtn");
      for (var j = 0; j < bs.length; j++) bs[j].classList.toggle("actif", bs[j] === t);
      dessinerZone(zone);
    });
    grpbar.appendChild(t);
    cles.forEach(function (g) {
      var b = document.createElement("button");
      b.className = "gbtn";
      b.innerHTML = g + '' +
        zone.noeuds.filter(function (n) { return groupeDe(n) === g; }).length + '';
      b.addEventListener("click", function () {
        groupeActif = g;
        var bs = grpbar.querySelectorAll(".gbtn");
        for (var j = 0; j < bs.length; j++) bs[j].classList.toggle("actif", bs[j] === b);
        dessinerZone(zone);
      });
      grpbar.appendChild(b);
    });
  }

  /* ---------- légende ---------- */
  var leg = document.getElementById("legende");
  Object.keys(COULEURS).forEach(function (t) {
    var sp = document.createElement("span");
    sp.appendChild(icone(t, 16));
    sp.appendChild(document.createTextNode(LIBELLES[t]));
    leg.appendChild(sp);
  });

  function positionner(zone, W, H) {
    var ordre = zone.noeuds.slice().sort(function (a, b) {
      return a.nom.localeCompare(b.nom); });
    var n = ordre.length;
    var COLS = Math.max(2, Math.min(7, Math.ceil(Math.sqrt(n * W / H))));
    var ROWS = Math.ceil(n / COLS);
    var PAD = 70, CELL = Math.min(150, (W - 2*PAD) / COLS - 16), CH = 74;
    var gx = (W - 2*PAD - CELL) / Math.max(1, COLS - 1);
    var gy = (H - 2*PAD - CH) / Math.max(1, ROWS - 1);
    var pos = {};
    ordre.forEach(function (nd, idx) {
      var r = Math.floor(idx / COLS), c = idx % COLS;
      pos[nd.id] = {x: PAD + c*gx, y: PAD + r*gy, w: CELL, h: CH};
    });
    return {pos: pos, ordre: ordre};
  }

  function piste(pos, a, b) {
    var A = pos[a], B = pos[b]; if (!A || !B) return null;
    var x1 = A.x + A.w/2, y1 = A.y + A.h;
    var x2 = B.x + B.w/2, y2 = B.y;
    var my = (y1 + y2) / 2;
    return "M"+x1+" "+y1+" L"+x1+" "+my+" L"+x2+" "+my+" L"+x2+" "+y2;
  }

  /* ---------- la popup ---------- */
  var popup = document.getElementById("popup");
  var popNom = document.getElementById("pop-nom");
  var popType = document.getElementById("pop-type");
  var popIcone = document.getElementById("pop-icone");
  var popOnglets = document.getElementById("pop-onglets");
  var popContenu = document.getElementById("pop-contenu");
  document.getElementById("pop-fermer").addEventListener("click", fermer);
  popup.addEventListener("click", function (e) { if (e.target === popup) fermer(); });
  function fermer() { popup.classList.remove("ouvert"); }

  var zoneCourante = null, noeudCourant = null;
  function ouvrir(zone, nd) {
    zoneCourante = zone; noeudCourant = nd;
    popNom.textContent = nd.nom;
    popType.textContent = (LIBELLES[nd.type] || nd.type) + " · " + zone.nom;
    while (popIcone.firstChild) popIcone.removeChild(popIcone.firstChild);
    popIcone.appendChild(icone(nd.type, 34));
    var noms = ["Config"];
    var liens = zone.liens.filter(function (l) {
      return l.de === nd.id || l.vers === nd.id; });
    var webapps = webappsDe(nd);
    if (webapps.length) noms.push("Webapps");
    if (liens.length) noms.push("Connexions");
    while (popOnglets.firstChild) popOnglets.removeChild(popOnglets.firstChild);
    noms.forEach(function (nom, i) {
      var b = document.createElement("button");
      b.textContent = nom + (nom === "Connexions" ? " (" + liens.length + ")" :
        nom === "Webapps" ? " (" + webapps.length + ")" : "");
      b.className = i === 0 ? "actif" : "";
      b.addEventListener("click", function () {
        var bs = popOnglets.querySelectorAll("button");
        for (var j = 0; j < bs.length; j++) bs[j].classList.toggle("actif", j === i);
        remplir(nom);
      });
      popOnglets.appendChild(b);
    });
    remplir("Config");
    popup.classList.add("ouvert");
  }

  function webappsDe(nd) {
    var zoneWeb = D.zones.filter(function (z) { return z.id === "webapps"; })[0];
    if (!zoneWeb) return [];
    var res = [];
    zoneWeb.liens.forEach(function (l) {
      if (l.vers === nd.id && l.quoi === "servi par") {
        var w = zoneWeb.noeuds.filter(function (x) { return x.id === l.de; })[0];
        if (w) res.push(w);
      }
    });
    return res;
  }

  function remplir(onglet) {
    while (popContenu.firstChild) popContenu.removeChild(popContenu.firstChild);
    var nd = noeudCourant, zone = zoneCourante;
    if (onglet === "Config") {
      ligne("type", LIBELLES[nd.type] || nd.type);
      if (nd.detail) ligne("détail", nd.detail);
      ligne("id", nd.id);
      var liens = zone.liens.filter(function (l) {
        return l.de === nd.id || l.vers === nd.id; });
      ligne("connexions", liens.length + " lien(s)");
      ligne("zone", zone.id);
    } else if (onglet === "Webapps") {
      var ws = webappsDe(nd);
      if (!ws.length) { vide(); return; }
      ws.forEach(function (w) {
        var d = document.createElement("div");
        d.className = "webapp";
        var gauche = document.createElement("span");
        gauche.className = "wa-nom"; gauche.textContent = w.nom;
        var droite = document.createElement("span");
        droite.className = "wa-url"; droite.textContent = (w.detail || "");
        d.appendChild(gauche); d.appendChild(droite);
        popContenu.appendChild(d);
      });
    } else if (onglet === "Connexions") {
      var liens = zone.liens.filter(function (l) {
        return l.de === nd.id || l.vers === nd.id; });
      if (!liens.length) { vide(); return; }
      liens.forEach(function (l) {
        var de = nomDans(l.de), vers = nomDans(l.vers);
        var d = document.createElement("div");
        d.className = "ligne";
        var k = document.createElement("span"); k.className = "k"; k.textContent = l.quoi;
        var v = document.createElement("span"); v.className = "v";
        v.textContent = de + " → " + vers;
        d.appendChild(k); d.appendChild(v);
        popContenu.appendChild(d);
      });
    }
  }
  function nomDans(id) {
    var z = zoneCourante;
    var nd = z.noeuds.filter(function (x) { return x.id === id; })[0];
    return nd ? nd.nom : id;
  }
  function ligne(k, v) {
    var d = document.createElement("div"); d.className = "ligne";
    var kk = document.createElement("span"); kk.className = "k"; kk.textContent = k;
    var vv = document.createElement("span"); vv.className = "v"; vv.textContent = v;
    d.appendChild(kk); d.appendChild(vv); popContenu.appendChild(d);
  }
  function vide() {
    var d = document.createElement("div"); d.className = "vide";
    d.textContent = "rien à montrer ici.";
    popContenu.appendChild(d);
  }

  /* ---------- dessin ---------- */
  var posActuelle = {};
  function dessiner(i) {
    var zone = D.zones[i];
    groupeActif = null;
    var btns = document.querySelectorAll(".zbtn");
    for (var b = 0; b < btns.length; b++) btns[b].classList.toggle("actif", b === i);
    construireGroupes(zone);
    dessinerZone(zone);
  }
  function dessinerZone(zone) {
    document.getElementById("desc").textContent = zone.description;
    var noeuds = zone.noeuds;
    var liens = zone.liens;
    if (groupeActif) {
      noeuds = zone.noeuds.filter(function (n) { return groupeDe(n) === groupeActif; });
      var ids = {};
      noeuds.forEach(function (n) { ids[n.id] = true; });
      liens = zone.liens.filter(function (l) {
        return ids[l.de] && ids[l.vers]; });
    }
    var W = 1500, H = Math.max(640, Math.ceil(noeuds.length/7)*92 + 150);
    svg.setAttribute("viewBox", "0 0 " + W + " " + H);
    while (svg.firstChild) svg.removeChild(svg.firstChild);

    var zoneF = {noeuds: noeuds, liens: liens};
    var lay = positionner(zoneF, W, H);
    posActuelle = lay.pos;
    svg.appendChild(el("rect", {x:0, y:0, width:W, height:H, fill:"#0b1210"}));

    for (var gx = 0; gx < W; gx += 40) el("line", {x1:gx, y1:0, x2:gx, y2:H,
      stroke:"#0d1526", "stroke-width":1}, svg);
    for (var gy = 0; gy < H; gy += 40) el("line", {x1:0, y1:gy, x2:W, y2:gy,
      stroke:"#0d1526", "stroke-width":1}, svg);

    var t = el("text", {x:W/2, y:34, "text-anchor":"middle", "font-size":15,
      "font-weight":600, fill:"#d4e6da", "font-family":"ui-monospace,monospace"});
    t.textContent = zone.nom.toUpperCase() +
      (groupeActif ? " — " + groupeActif : "") +
      " — " + noeuds.length + " éléments";
    svg.appendChild(t);

    liens.forEach(function (lk) {
      var d = piste(posActuelle, lk.de, lk.vers); if (!d) return;
      var p = el("path", {d:d, "class":"piste"});
      p.dataset.de = lk.de; p.dataset.vers = lk.vers;
      svg.appendChild(p);
    });

    lay.ordre.forEach(function (nd) {
      var p = posActuelle[nd.id]; if (!p) return;
      var g = el("g", {"class":"noeud", transform:"translate("+p.x+","+p.y+")"});
      var ic = icone(nd.type, 36);
      ic.setAttribute("transform", "translate("+(p.w/2-18)+",2)");
      g.appendChild(ic);
      var e = el("text", {x:p.w/2, y:50, "class":"etiquette"});
      e.textContent = nd.nom.length > 20 ? nd.nom.slice(0,19)+"…" : nd.nom;
      g.appendChild(e);
      var s = el("text", {x:p.w/2, y:64, "class":"soustype"});
      s.textContent = LIBELLES[nd.type] || nd.type;
      g.appendChild(s);
      var clic = el("rect", {x:-6, y:-4, width:p.w+12, height:74, rx:8,
        fill:"transparent", "class":"fond", stroke:"none"});
      g.insertBefore(clic, ic);
      g.addEventListener("click", function () { ouvrir(zone, nd); });
      g.addEventListener("mouseenter", function () {
        svg.querySelectorAll(".piste").forEach(function (x) {
          x.classList.toggle("actif", x.dataset.de === nd.id || x.dataset.vers === nd.id);
        });
      });
      g.addEventListener("mouseleave", function () {
        svg.querySelectorAll(".piste").forEach(function (x) {
          x.classList.remove("actif");
        });
      });
      svg.appendChild(g);
    });
  }

  dessiner(0);
})();
